CREATE TABLE IF NOT EXISTS inec_live_api_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), canonical_source_key text NOT NULL, endpoint_path text NOT NULL, request_query jsonb NOT NULL, http_status integer NOT NULL, content_type text, byte_size integer NOT NULL, response_sha256 text, response_json jsonb, acquisition_status text NOT NULL, provenance_status text NOT NULL DEFAULT 'SOURCE_BOUND', acquired_at timestamptz NOT NULL DEFAULT now(), UNIQUE(canonical_source_key,endpoint_path,request_query));
CREATE TABLE IF NOT EXISTS inec_candidate_live_crosswalks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, state_id integer, lga_id integer, official_lga_name text, official_ward_count integer NOT NULL DEFAULT 0, lga_snapshot_id uuid, ward_snapshot_id uuid, match_status text NOT NULL DEFAULT 'CANDIDATE_MATCH_ONLY', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(candidate_match_id));